$_pf_factor = 1 + $_pf_markup / 100;
$_prange = $this->db->query("SELECT MIN(p.price) AS mn, MAX(p.price) AS mx FROM " . DB_PREFIX . "product p LEFT JOIN " . DB_PREFIX . "product_to_category p2c ON p.product_id = p2c.product_id WHERE p2c.category_id = '" . (int)$category_id . "' AND p.status = '1'");
$_cat_price_min = isset($_prange->row['mn']) && $_prange->row['mn'] !== null ? (float)$_prange->row['mn'] * $_pf_factor : 0;
